### cot
Step 1. Check if the source and destination folders exist. If not, return a failure dictionary.
Step 2. Identify all files within the source folder using `glob`.
Step 3. Iterate through each file found.
Step 4. For each file, attempt to compress it using the `gzip` command via `subprocess.run`.
Step 5. If compression is successful, move the resulting `.gz` file to the destination folder using `shutil.move`.
Step 6. Keep track of any files that fail either the compression or move step.
Step 7. Return a dictionary containing the success status, a summary message, and the list of failed files.

### code
```python
import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []

    for file_path in files:
        try:
            result = subprocess.run(['gzip', '-c', file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
            gz_path = file_path + '.gz'
            with open(gz_path, 'wb') as f:
                f.write(result.stdout)
            shutil.move(gz_path, os.path.join(dst_folder, os.path.basename(gz_path)))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    else:
        return {'success': False, 'message': 'Some files failed to process', 'failed_files': failed_files}
